const rawInput = $input.first().json;
const errors = [];

// Валидационна проверка
if (!rawInput.email || typeof rawInput.email !== 'string' || !rawInput.email.includes('@')) {
  errors.push('Невалиден или липсващ email адрес');
}
if (!rawInput.company_name && !rawInput.name) {
  errors.push('Липсва име на компания или лице');
}

const needsManual = errors.length > 0 || rawInput.has_exception === true;

return {
  json: {
    client_id: rawInput.client_id || rawInput.id || null,
    email: rawInput.email || null,
    phone: rawInput.phone || null,
    company_name: rawInput.company_name || rawInput.name || null,
    status: needsManual ? 'NEEDS_MANUAL_REVIEW' : (rawInput.status || 'PROCESSED'),
    validation_errors: errors,
    rejection_reason: errors.join('; ') || rawInput.error_message || null,
    raw_payload: rawInput, // Пълно запазване на входните данни
    source_workflow: $workflow.name,
    is_manual_review: needsManual,
    updated_at: new Date().toISOString()
  }
};
